using namespace std;

class Solution {
    vector<int> getPalindromeLengths(const string& str, bool isSuffix) {
        int len = str.length();
        vector<vector<bool>> dp(len, vector<bool>(len, false));
        vector<int> lengths(len, 0);
        for (int i = len - 1; i >= 0; --i) {
            for (int j = i; j < len; ++j) {
                if (str[i] == str[j] && (j - i < 2 || dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                    int idx = isSuffix ? i : j;
                    lengths[idx] = max(lengths[idx], j - i + 1);
                }
            }
        }
        return lengths;
    }

public:
    int longestPalindrome(string s, string t) {
        int m = s.length(), n = t.length();
        vector<int> suffix = getPalindromeLengths(s, true);
        vector<int> prefix = getPalindromeLengths(t, false);

        int ans = 0;
        for (int x : suffix) ans = max(ans, x);
        for (int x : prefix) ans = max(ans, x);

        vector<vector<int>> dp(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = n - 1; j >= 0; --j) {
                if (s[i] == t[j]) {
                    dp[i][j] = 2 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1] : 0);
                    int extend = max(i + 1 < m ? suffix[i + 1] : 0, j > 0 ? prefix[j - 1] : 0);
                    ans = max(ans, dp[i][j] + extend);
                }
            }
        }

        return ans;
    }
};

import java.util.*;

class Solution {
    private int[] getPalindromeLengths(String str, boolean isSuffix) {
        int len = str.length();
        boolean[][] dp = new boolean[len][len];
        int[] lengths = new int[len];
        for (int i = len - 1; i >= 0; i--) {
            for (int j = i; j < len; j++) {
                if (str.charAt(i) == str.charAt(j) && (j - i < 2 || dp[i + 1][j - 1])) {
                    dp[i][j] = true;
                    int idx = isSuffix ? i : j;
                    lengths[idx] = Math.max(lengths[idx], j - i + 1);
                }
            }
        }
        return lengths;
    }

    public int longestPalindrome(String s, String t) {
        int m = s.length(), n = t.length();
        int[] suffix = getPalindromeLengths(s, true);
        int[] prefix = getPalindromeLengths(t, false);

        int ans = 0;
        for (int x : suffix) ans = Math.max(ans, x);
        for (int x : prefix) ans = Math.max(ans, x);

        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = n - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    dp[i][j] = 2 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1] : 0);
                    int extend = Math.max(i + 1 < m ? suffix[i + 1] : 0, j > 0 ? prefix[j - 1] : 0);
                    ans = Math.max(ans, dp[i][j] + extend);
                }
            }
        }

        return ans;
    }
}

